import pytest

from bedrock_protocol import v1001, v2168, v2225

# generated by gophertunnel b8bd735:
# &packet.CameraAimAssist{Preset: "aim_assist_preset", Angle: mgl32.Vec2{30, 20}, Distance: 8, TargetMode:
# protocol.AimAssistTargetModeDistance, Action: packet.CameraAimAssistActionSet, ShowDebugRender: true}
CAMERA_AIM_ASSIST = bytes.fromhex("1161696d5f6173736973745f7072657365740000f0410000a04100000041010001")

# generated by gophertunnel b8bd735:
# &packet.CameraAimAssist{Preset: strings.Repeat("p", 200), Action: packet.CameraAimAssistActionClear}
LONG_PRESET = bytes.fromhex(
    ""
)

GOLDENS = [
    pytest.param(
        v2225.CameraAimAssistPacket(
            preset_id="aim_assist_preset",
            view_angle=v2225.Vec2(x=30.0, y=20.0),
            distance=8.0,
            target_mode=v2225.CameraAimAssistPacket.TargetMode.DISTANCE,
            action=v2225.CameraAimAssistPacket.Action.SET,
            show_debug_render=True,
        ),
        CAMERA_AIM_ASSIST,
        id="distance-set",
    ),
    pytest.param(
        v2225.CameraAimAssistPacket(preset_id="p" * 200, action=v2225.CameraAimAssistPacket.Action.CLEAR),
        LONG_PRESET,
        id="200-byte-preset-id",
    ),
]


@pytest.mark.parametrize("version", [v1001, v2168, v2225], ids=lambda version: version.__name__.rpartition(".")[2])
def test_camera_aim_assist_is_packet_316(version):
    assert version.PACKETS[316] is version.CameraAimAssistPacket


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_camera_aim_assist_encodes_to_its_golden(packet, golden):
    assert bytes(packet) == golden


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_camera_aim_assist_decodes_from_its_golden(packet, golden):
    assert v2225.CameraAimAssistPacket.from_bytes(golden) == packet
